import 'package:flutter/material.dart';import 'package:sheshield/screens/guardian_dashboard_screen.dart';import 'package:sheshield/services/guardian_service.dart';
class GuardianLoginScreen extends StatefulWidget{const GuardianLoginScreen({super.key});@override State<GuardianLoginScreen>createState()=>_State();}class _State extends State<GuardianLoginScreen>{final email=TextEditingController(),code=TextEditingController();bool busy=false;String?error;Future<void>login()async{setState((){busy=true;error=null;});try{final token=await GuardianService().login(email.text.trim(),code.text.trim());if(mounted)Navigator.of(context).pushReplacement(MaterialPageRoute(builder:(_)=>GuardianDashboardScreen(token:token)));}catch(e){if(mounted)setState(()=>error='$e');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Guardian Login')),body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:480),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.family_restroom,size:72,color:Color(0xFF8E3A62)),const Text('Monitor Student Safety',textAlign:TextAlign.center,style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:24),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Student Email')),const SizedBox(height:14),TextField(controller:code,keyboardType:TextInputType.number,maxLength:6,decoration:const InputDecoration(labelText:'6-digit Pairing Code')),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error)),FilledButton(onPressed:busy?null:login,child:Text(busy?'Connecting...':'Open Guardian Dashboard'))])))));}
